const b = $json.body || $json;
const paquetes = new Set(['setup', 'mensual', 'pico']);
const paquete = String(b.paquete || 'setup').trim().toLowerCase();
const marca = String(b.marca || b.nombre || '').trim();
const whatsapp = String(b.whatsapp || '').trim();
const rubro = String(b.rubro || 'local').trim();
if (!paquetes.has(paquete)) return [{ json: { ok: false, error: 'paquete inválido', paquetes: [...paquetes] } }];
if (!marca) return [{ json: { ok: false, error: 'falta marca' } }];
const slug = marca.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
return [{ json: {
  ok: true,
  sistema: '08-cola-pedidos-wasap',
  etapa: 'alta_negocio',
  jobId: `COL-${Date.now()}`,
  slug, marca, rubro, whatsapp, paquete,
  status: 'onboarding',
  apps: ['whatsapp-meta', 'n8n', 'sheet/notion'],
  todo: 'TODO: clientes/{slug}/ + activar webhooks Meta',
  at: new Date().toISOString()
}}];
